mapper.insert:
/* AppReq07Mapper.insertAttdReq */
INSERT INTO TB_USER_ATTD_REQ (
      REQ_ID
    , CMPNY_CD
    , SITE_CD
    , USER_CD
    , REQ_TYPE
    , TARGET_ID
    , REQ_STATUS
    , REQ_REASON
    , WORK_YMD
    , NODE_CD
    , WORK_SEQ
    , START_DATE
    , START_TIME
    , END_DATE
    , END_TIME
    , SCH_CD
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{reqId}
    , #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{reqType}
    , #{targetId}
    , #{reqStatus}
    , #{reqReason}
    , #{workYmd}
    , #{nodeCd}
    , #{workSeq}
    , #{startDate}
    , #{startTime}
    , #{endDate}
    , #{endTime}
    , #{schCd}
    , 'N'
    , #{insertNo}
    , NOW()
)

mapper.select:
/* AppReq07Mapper.countDuplicateReq */
SELECT COUNT(1)
  FROM TB_USER_ATTD_REQ A
 WHERE A.CMPNY_CD   = #{cmpnyCd}
   AND A.SITE_CD    = #{siteCd}
   AND A.USER_CD    = #{userCd}
   AND A.WORK_YMD   = #{workYmd}
   AND A.REQ_TYPE   = #{reqType}
   AND A.REQ_STATUS = '01'
   AND A.DEL_YN     = 'N'

/* AppReq07Mapper.selectExistingAttdId */
SELECT A.ATTD_ID
  FROM TB_USER_ATTD_MGMT A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.SITE_CD  = #{siteCd}
   AND A.USER_CD  = #{userCd}
   AND A.WORK_YMD = #{workYmd}
   AND A.WORK_SEQ = #{workSeq}
   AND A.DEL_YN   = 'N'
 LIMIT 1

/* AppReq07Mapper.selectUserDefaultSchCd */
SELECT U.DEFAULT_SCH_CD
  FROM TB_USER U
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.USER_CD  = #{userCd}
 LIMIT 1

/* AppReq07Mapper.selectWorkPlanSchedule */ SELECT S.SCH_CD AS schCd , S.FST_SCH_STR_TIME AS fstStrTime , S.FST_SCH_END_TIME AS fstEndTime , S.SEC_SCH_STR_TIME AS secStrTime , S.SEC_SCH_END_TIME AS secEndTime FROM TB_USER_WORK_PLAN P
INNER JOIN ( SELECT E.CMPNY_CD, E.SITE_CD, E.SCH_CD, E.APPLY_DATE , E.FST_SCH_STR_TIME, E.FST_SCH_END_TIME , E.SEC_SCH_STR_TIME, E.SEC_SCH_END_TIME FROM ( SELECT M.CMPNY_CD, M.SITE_CD, M.SCH_CD, M.APPLY_DATE , M.FST_SCH_STR_TIME, M.FST_SCH_END_TIME , M.SEC_SCH_STR_TIME, M.SEC_SCH_END_TIME , 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M UNION ALL SELECT H.CMPNY_CD, H.SITE_CD, H.SCH_CD, H.APPLY_DATE , H.FST_SCH_STR_TIME, H.FST_SCH_END_TIME , H.SEC_SCH_STR_TIME, H.SEC_SCH_END_TIME , H.HIST_IDX FROM TB_SCH_MGMT_HIST H ) E WHERE E.HIST_IDX = ( SELECT MAX(E2.HIST_IDX) FROM ( SELECT M2.CMPNY_CD, M2.SITE_CD, M2.SCH_CD, M2.APPLY_DATE, 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M2 UNION ALL SELECT H2.CMPNY_CD, H2.SITE_CD, H2.SCH_CD, H2.APPLY_DATE, H2.HIST_IDX FROM TB_SCH_MGMT_HIST H2 ) E2 WHERE E2.CMPNY_CD = E.CMPNY_CD AND E2.SITE_CD = E.SITE_CD AND E2.SCH_CD = E.SCH_CD AND E2.APPLY_DATE = E.APPLY_DATE ) ) S ON S.CMPNY_CD = P.CMPNY_CD AND S.SITE_CD = P.SITE_CD AND S.SCH_CD = P.WORK_PLAN_CD AND S.APPLY_DATE = (
SELECT COALESCE( MAX(CASE WHEN SE.APPLY_DATE <= P.WORK_YMD THEN SE.APPLY_DATE END) , MIN(SE.APPLY_DATE) ) FROM ( SELECT M3.CMPNY_CD, M3.SITE_CD, M3.SCH_CD, M3.APPLY_DATE FROM TB_SCH_MGMT M3 UNION ALL SELECT H3.CMPNY_CD, H3.SITE_CD, H3.SCH_CD, H3.APPLY_DATE FROM TB_SCH_MGMT_HIST H3 ) SE WHERE SE.CMPNY_CD = P.CMPNY_CD AND SE.SITE_CD = P.SITE_CD AND SE.SCH_CD = P.WORK_PLAN_CD ) WHERE P.CMPNY_CD = #{cmpnyCd} AND P.SITE_CD = #{siteCd} AND P.USER_CD = #{userCd} AND P.WORK_YMD = #{workYmd} LIMIT 1

/* AppReq07Mapper.countPendingAttdCorrectionBySlot */
SELECT COUNT(1)
  FROM TB_USER_ATTD_REQ A
 WHERE A.CMPNY_CD   = #{cmpnyCd}
   AND A.SITE_CD    = #{siteCd}
   AND A.USER_CD    = #{userCd}
   AND A.WORK_YMD   = #{workYmd}
   AND A.WORK_SEQ   = #{workSeq}
   AND A.REQ_TYPE   IN ('01', '02')
   AND A.REQ_STATUS = '01'
   AND A.DEL_YN     = 'N'

/* AppReq07Mapper.countActiveSchedModify */
SELECT COUNT(1)
  FROM TB_USER_ATTD_REQ A
 WHERE A.CMPNY_CD   = #{cmpnyCd}
   AND A.SITE_CD    = #{siteCd}
   AND A.USER_CD    = #{userCd}
   AND A.WORK_YMD   = #{workYmd}
   AND A.REQ_TYPE   = '10'
   AND A.REQ_STATUS = '01'
   AND A.DEL_YN     = 'N'

/* AppReq07Mapper.countActiveOvertimeReq */
SELECT COUNT(1)
  FROM TB_USER_ATTD_REQ A
 WHERE A.CMPNY_CD   = #{cmpnyCd}
   AND A.SITE_CD    = #{siteCd}
   AND A.USER_CD    = #{userCd}
   AND A.WORK_YMD   = #{workYmd}
   AND A.REQ_TYPE   IN ('03', '04')
   AND A.REQ_STATUS = '01'
   AND A.DEL_YN     = 'N'

/* AppReq07Mapper.selectActualAttdWindowBySlot */
SELECT A.CHECK_IN_DATE   AS checkInDate
     , A.CHECK_IN_TIME   AS checkInTime
     , A.CHECK_OUT_DATE  AS checkOutDate
     , A.CHECK_OUT_TIME  AS checkOutTime
  FROM TB_USER_ATTD_MGMT A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.SITE_CD  = #{siteCd}
   AND A.USER_CD  = #{userCd}
   AND A.WORK_YMD = #{workYmd}
   AND A.WORK_SEQ = #{workSeq}
   AND A.DEL_YN   = 'N'
 LIMIT 1

/* AppReq07Mapper.countUserWorkPlan */
SELECT COUNT(1)
  FROM TB_USER_WORK_PLAN P
 WHERE P.CMPNY_CD = #{cmpnyCd}
   AND P.SITE_CD  = #{siteCd}
   AND P.USER_CD  = #{userCd}
   AND P.WORK_YMD = #{workYmd}

/* AppReq07Mapper.countActiveOvertimeOutsideAttdWindow - OT must stay within new attd window */
SELECT COUNT(*)
FROM TB_USER_OVERTIME_MGMT O
WHERE O.CMPNY_CD = #{cmpnyCd}
  AND O.SITE_CD  = #{siteCd}
  AND O.USER_CD  = #{userCd}
  AND O.ATTD_ID  = #{attdId}
  AND O.DEL_YN   = 'N'
  AND O.OT_STATUS  <>  'CANCELLED'
  AND (
    CONCAT(O.ACTUAL_START_DATE, O.ACTUAL_START_TIME)  <  #{newStart}
    OR O.ACTUAL_END_DATE IS NULL
    OR O.ACTUAL_END_TIME IS NULL



        OR 1 = 1


        OR CONCAT(O.ACTUAL_END_DATE, O.ACTUAL_END_TIME)  >  #{newEnd}


  )
